const flowers=[{id:1,name:'落日来信',en:'SUNSET LETTER · 玫瑰混合花束',price:268,category:'gift',tag:'THE FAVORITE',image:'photo-1563241527-3004b7be0ffd'},{id:2,name:'白日梦',en:'A DAYDREAM · 自然白绿花束',price:238,category:'daily',tag:'SLOW LIVING',image:'photo-1525310072745-f49212b5ac6d'},{id:3,name:'粉色心事',en:'A LITTLE CRUSH · 浪漫粉调花束',price:298,category:'gift',tag:'JUST FOR YOU',image:'photo-1526045478516-99145907023c'}];let bag=[];try{bag=JSON.parse(localStorage.getItem('flora-bag')||'[]').filter(id=>flowers.some(f=>f.id===id))}catch{}const products=document.querySelector('#products');function render(filter='all'){products.innerHTML=flowers.filter(f=>filter==='all'||f.category===filter).map(f=>`<article class="product"><div class="product-image"><img loading="lazy" src="https://images.unsplash.com/${f.image}?auto=format&fit=crop&w=800&q=85" alt="${f.name}花束"><span class="tag">${f.tag}</span><button class="add" data-add="${f.id}" aria-label="将${f.name}加入花袋">＋</button></div><div class="product-title"><h3>${f.name}</h3><span>¥ ${f.price}</span></div><p>${f.en}</p></article>`).join('')}function update(){document.querySelector('#count').textContent=bag.length;try{localStorage.setItem('flora-bag',JSON.stringify(bag))}catch{}document.querySelector('#bag-items').innerHTML=bag.length?bag.map((id,i)=>{const f=flowers.find(f=>f.id===id);return `<div class="bag-row"><span>${f.name} · ¥${f.price}</span><button data-remove="${i}">移除</button></div>`}).join(''):'<p class="dialog-intro">花袋还是空的，先去挑一束喜欢的花吧。</p>';document.querySelector('#total').textContent=bag.length?'合计 ¥ '+bag.reduce((s,id)=>s+flowers.find(f=>f.id===id).price,0):''}document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');render(b.dataset.filter)});let timer;products.onclick=e=>{const b=e.target.closest('[data-add]');if(!b)return;bag.push(Number(b.dataset.add));update();const toast=document.querySelector('#toast');toast.textContent='已加入心愿花袋 ✿';toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),2200)};const drawer=document.querySelector('#drawer');document.querySelector('#bag').onclick=()=>drawer.showModal();document.querySelector('#close').onclick=()=>drawer.close();drawer.onclick=e=>{if(e.target===drawer){const r=drawer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)drawer.close()}};document.querySelector('#bag-items').onclick=e=>{const b=e.target.closest('[data-remove]');if(b){bag.splice(Number(b.dataset.remove),1);update()}};render();update();
